insert into public.films (id, slug, title, original_title, year, type, countries, languages, genres, synopsis, awards, status, featured) values
('33af8709-e3a1-54fe-afff-687934a5b64a', 'within-our-gates', 'Within Our Gates', null, 1920, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A young Black teacher travels north to raise money for a struggling Southern school. The oldest surviving feature by an African American director, made as a direct answer to The Birth of a Nation.', '[{"award":"National Film Registry","category":"Selected","result":"won","year":1992}]'::jsonb, 'published', false),
('a7dcfbe1-20cb-5791-a40d-0e336271a337', 'the-learning-tree', 'The Learning Tree', null, 1969, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A teenager comes of age in 1920s Kansas, facing love, racism and a murder he witnessed. Parks adapted his own semi-autobiographical novel.', '[{"award":"National Film Registry","category":"Selected","result":"won","year":1989}]'::jsonb, 'published', false),
('2d7908e9-683a-5b77-a6a2-abee5a1f1292', 'shaft', 'Shaft', null, 1971, 'feature', array['US']::text[], array['English']::text[], array['Crime','Action']::text[], 'A private detective is hired by a Harlem crime boss to find his kidnapped daughter. Isaac Hayes'' theme became as famous as the film.', '[{"award":"Academy Awards","category":"Best Original Song","result":"won","year":1972},{"award":"National Film Registry","category":"Selected","result":"won","year":2000}]'::jsonb, 'published', false),
('05a5cc63-68f7-5e01-a71b-ef6338e52f9a', 'sweet-sweetback-s-baadasssss-song', 'Sweet Sweetback''s Baadasssss Song', null, 1971, 'feature', array['US']::text[], array['English']::text[], array['Drama','Crime']::text[], 'After stopping two police officers from beating a young activist, a man goes on the run across Los Angeles. Made independently and defiantly, it became a box-office phenomenon.', '[]'::jsonb, 'published', false),
('33a051c9-5b45-56f7-aee5-ddd83579b0d2', 'ganja-and-hess', 'Ganja & Hess', null, 1973, 'feature', array['US']::text[], array['English']::text[], array['Horror','Drama']::text[], 'An anthropologist is stabbed with a cursed ancient dagger and becomes addicted to blood. A hypnotic, experimental film about faith, desire and assimilation.', '[]'::jsonb, 'published', false),
('50df269a-ca3d-57a4-a5ae-26848377382b', 'killer-of-sheep', 'Killer of Sheep', null, 1978, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A slaughterhouse worker in Watts drifts through his days, numbed by work and money worries. Shot on weekends for under $10,000, it waited almost thirty years for a proper release.', '[{"award":"National Film Registry","category":"Selected","result":"won","year":1990},{"award":"Berlin International Film Festival","category":"FIPRESCI Prize","result":"won","year":1981}]'::jsonb, 'published', true),
('4dd4af75-1f1f-577b-a937-5bc9a19bc8f1', 'losing-ground', 'Losing Ground', null, 1982, 'feature', array['US']::text[], array['English']::text[], array['Drama','Comedy']::text[], 'A philosophy professor researching ecstatic experience spends a summer upstate with her painter husband, and starts to find some ecstasy of her own.', '[]'::jsonb, 'published', false),
('19e7f5c6-6424-5955-a1e7-ab8b29b9db54', 'bless-their-little-hearts', 'Bless Their Little Hearts', null, 1984, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'An unemployed father in Watts struggles to hold on to his dignity and his family. Written and shot by Charles Burnett.', '[]'::jsonb, 'published', false),
('70d2c46e-359a-5d75-a483-53502176ae55', 'hollywood-shuffle', 'Hollywood Shuffle', null, 1987, 'feature', array['US']::text[], array['English']::text[], array['Comedy']::text[], 'An aspiring actor auditions for the only roles Hollywood offers Black men: pimps, gangsters and butlers. A satire told in sketches and daydreams.', '[]'::jsonb, 'published', false),
('199e7db2-9adc-5771-a383-ab8b2f2ebc49', 'do-the-right-thing', 'Do the Right Thing', null, 1989, 'feature', array['US']::text[], array['English']::text[], array['Drama','Comedy']::text[], 'On the hottest day of the year on one Brooklyn block, tensions between neighbors, a pizzeria owner and the police build towards an explosion.', '[{"award":"Academy Awards","category":"Best Original Screenplay","result":"nominated","year":1990},{"award":"Academy Awards","category":"Best Supporting Actor (Danny Aiello)","result":"nominated","year":1990},{"award":"National Film Registry","category":"Selected","result":"won","year":1999}]'::jsonb, 'published', true),
('f6e13c6c-aaa3-53c5-a6fc-8a31042e3df6', 'tongues-untied', 'Tongues Untied', null, 1989, 'documentary', array['US']::text[], array['English']::text[], array['Documentary']::text[], 'Poetry, performance and testimony from Black gay men, including Riggs himself and the poet Essex Hemphill. Its broadcast on public television caused a national controversy.', '[]'::jsonb, 'published', false),
('e6c39113-e713-5387-a320-a26ae65eed5d', 'to-sleep-with-anger', 'To Sleep with Anger', null, 1990, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A charming old friend from the South arrives at a Los Angeles family''s home and slowly turns everyone against each other.', '[{"award":"Independent Spirit Awards","category":"Best Director","result":"won","year":1991},{"award":"Independent Spirit Awards","category":"Best Screenplay","result":"won","year":1991},{"award":"Independent Spirit Awards","category":"Best Male Lead (Danny Glover)","result":"won","year":1991},{"award":"National Film Registry","category":"Selected","result":"won","year":2017}]'::jsonb, 'published', false),
('72ba06eb-6813-54a8-a5d8-35b0b1060d3d', 'boyz-n-the-hood', 'Boyz n the Hood', null, 1991, 'feature', array['US']::text[], array['English']::text[], array['Drama','Crime']::text[], 'Three friends grow up in South Central Los Angeles, where a father''s guidance is the thin line between a future and the street.', '[{"award":"Academy Awards","category":"Best Director","result":"nominated","year":1992},{"award":"Academy Awards","category":"Best Original Screenplay","result":"nominated","year":1992},{"award":"National Film Registry","category":"Selected","result":"won","year":2002}]'::jsonb, 'published', false),
('5abcfd8b-49a1-5bf2-ab56-fec5f83c85e5', 'daughters-of-the-dust', 'Daughters of the Dust', null, 1991, 'feature', array['US']::text[], array['English','Gullah']::text[], array['Drama']::text[], 'In 1902, three generations of Gullah women gather on an island off the coast of South Carolina on the eve of migrating north. A ravishing, non-linear film about memory and inheritance.', '[{"award":"Sundance Film Festival","category":"Excellence in Cinematography","result":"won","year":1991},{"award":"National Film Registry","category":"Selected","result":"won","year":2004}]'::jsonb, 'published', true),
('aed93e45-eaa0-54a4-af79-fdfe5ce726d9', 'malcolm-x', 'Malcolm X', null, 1992, 'feature', array['US']::text[], array['English']::text[], array['Biography','Drama']::text[], 'The life of Malcolm X, from street hustler and prisoner to minister of the Nation of Islam and international voice for Black liberation.', '[{"award":"Academy Awards","category":"Best Actor (Denzel Washington)","result":"nominated","year":1993},{"award":"Academy Awards","category":"Best Costume Design","result":"nominated","year":1993},{"award":"National Film Registry","category":"Selected","result":"won","year":2010}]'::jsonb, 'published', false),
('a04ffee9-3b3f-5988-a298-5b62cfd6e06a', 'sankofa', 'Sankofa', null, 1993, 'feature', array['US','GH','BF','DE']::text[], array['English']::text[], array['Drama']::text[], 'An African American model on a photo shoot at a Ghanaian slave fort is transported back in time to live as an enslaved woman on a plantation.', '[]'::jsonb, 'published', false),
('9ade0fe4-a64f-50e2-aa83-3bf2d5a59778', 'the-watermelon-woman', 'The Watermelon Woman', null, 1996, 'feature', array['US']::text[], array['English']::text[], array['Comedy','Drama']::text[], 'A video-store clerk sets out to make a documentary about a forgotten Black actress from the 1930s credited only as ''The Watermelon Woman''.', '[{"award":"Berlin International Film Festival","category":"Teddy Award","result":"won","year":1996},{"award":"National Film Registry","category":"Selected","result":"won","year":2021}]'::jsonb, 'published', false),
('85d21e2c-ff3b-5aa8-a4de-6cffacf14e6f', 'eve-s-bayou', 'Eve''s Bayou', null, 1997, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'In 1960s Louisiana, ten-year-old Eve sees something she shouldn''t, and the secrets of her prosperous family begin to unravel.', '[{"award":"Independent Spirit Awards","category":"Best First Feature","result":"won","year":1998},{"award":"National Film Registry","category":"Selected","result":"won","year":2018}]'::jsonb, 'published', false),
('5d4294a6-279f-5653-a5a1-bee52d339d98', 'love-and-basketball', 'Love & Basketball', null, 2000, 'feature', array['US']::text[], array['English']::text[], array['Romance','Drama']::text[], 'Two neighbors in Los Angeles fall in love with basketball, and each other, over thirteen years told in four quarters.', '[{"award":"Independent Spirit Awards","category":"Best First Screenplay","result":"won","year":2001}]'::jsonb, 'published', false),
('50e29bd6-7dc3-5b10-a4e1-d5313eb5a286', 'pariah', 'Pariah', null, 2011, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A Brooklyn teenager quietly embraces her identity as a lesbian, while trying to keep it hidden from her family.', '[{"award":"Sundance Film Festival","category":"Excellence in Cinematography","result":"won","year":2011}]'::jsonb, 'published', false),
('b9bd9707-c904-50d5-a541-048025bb148b', 'middle-of-nowhere', 'Middle of Nowhere', null, 2012, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A nurse puts her life on hold while her husband serves an eight-year prison sentence, until she begins to ask what she wants for herself.', '[{"award":"Sundance Film Festival","category":"Directing Award, U.S. Dramatic","result":"won","year":2012}]'::jsonb, 'published', false),
('db54b029-c00c-5043-a457-ca84d3dbc92e', 'fruitvale-station', 'Fruitvale Station', null, 2013, 'feature', array['US']::text[], array['English']::text[], array['Drama','Biography']::text[], 'The last day in the life of Oscar Grant, a 22-year-old shot by a transit police officer in Oakland on New Year''s Day, 2009.', '[{"award":"Sundance Film Festival","category":"Grand Jury Prize, U.S. Dramatic","result":"won","year":2013},{"award":"Sundance Film Festival","category":"Audience Award, U.S. Dramatic","result":"won","year":2013},{"award":"Cannes Film Festival","category":"Un Certain Regard, Prize of the Future","result":"won","year":2013}]'::jsonb, 'published', false),
('242834ee-c6fe-5d2c-ad58-02535951f5b7', '12-years-a-slave', '12 Years a Slave', null, 2013, 'feature', array['US','GB']::text[], array['English']::text[], array['Drama','Biography']::text[], 'Solomon Northup, a free Black man in New York, is kidnapped in 1841 and sold into slavery in Louisiana. Based on his own memoir.', '[{"award":"Academy Awards","category":"Best Picture","result":"won","year":2014},{"award":"Academy Awards","category":"Best Supporting Actress (Lupita Nyong''o)","result":"won","year":2014},{"award":"Academy Awards","category":"Best Adapted Screenplay","result":"won","year":2014},{"award":"BAFTA Awards","category":"Best Film","result":"won","year":2014}]'::jsonb, 'published', true),
('b7ec6a22-dd8d-53be-a027-8438475ca641', 'selma', 'Selma', null, 2014, 'feature', array['US','GB']::text[], array['English']::text[], array['Drama','History']::text[], 'Martin Luther King Jr. and the civil rights movement campaign for voting rights with a march from Selma to Montgomery, Alabama, in 1965.', '[{"award":"Academy Awards","category":"Best Original Song (\"Glory\")","result":"won","year":2015},{"award":"Academy Awards","category":"Best Picture","result":"nominated","year":2015}]'::jsonb, 'published', false),
('5ef6fb5c-1c6a-5bf1-a5f7-da557c055d91', '13th', '13th', null, 2016, 'documentary', array['US']::text[], array['English']::text[], array['Documentary']::text[], 'How the 13th Amendment''s exception for criminal punishment helped turn mass incarceration into a continuation of slavery.', '[{"award":"Academy Awards","category":"Best Documentary Feature","result":"nominated","year":2017}]'::jsonb, 'published', false),
('e406afea-6918-5e5a-a74f-7b7f2d2c13f4', 'moonlight', 'Moonlight', null, 2016, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'Three chapters in the life of Chiron, growing up in Miami: as a boy, a teenager and a man, searching for tenderness in a world that offers little.', '[{"award":"Academy Awards","category":"Best Picture","result":"won","year":2017},{"award":"Academy Awards","category":"Best Supporting Actor (Mahershala Ali)","result":"won","year":2017},{"award":"Academy Awards","category":"Best Adapted Screenplay","result":"won","year":2017},{"award":"Golden Globe Awards","category":"Best Motion Picture – Drama","result":"won","year":2017}]'::jsonb, 'published', true),
('dada7154-8595-550c-ad8f-db9b96ac06bf', 'get-out', 'Get Out', null, 2017, 'feature', array['US']::text[], array['English']::text[], array['Horror','Thriller']::text[], 'A young Black photographer visits his white girlfriend''s family for the weekend, and their welcome turns out to be far too warm.', '[{"award":"Academy Awards","category":"Best Original Screenplay","result":"won","year":2018},{"award":"Academy Awards","category":"Best Picture","result":"nominated","year":2018}]'::jsonb, 'published', true),
('9bbca26b-4b21-5344-a91a-db6bbb096592', 'mudbound', 'Mudbound', null, 2017, 'feature', array['US']::text[], array['English']::text[], array['Drama','History']::text[], 'Two families, one white and one Black, work the same land in the Mississippi Delta after the Second World War, as two returning veterans form a dangerous friendship.', '[{"award":"Academy Awards","category":"Best Supporting Actress (Mary J. Blige)","result":"nominated","year":2018},{"award":"Academy Awards","category":"Best Cinematography","result":"nominated","year":2018}]'::jsonb, 'published', false),
('3b7560ba-4029-597c-ae60-123c4faae1dd', 'black-panther', 'Black Panther', null, 2018, 'feature', array['US']::text[], array['English','Xhosa']::text[], array['Action','Science Fiction']::text[], 'T''Challa returns home to the hidden, technologically advanced African nation of Wakanda to take the throne, and faces a challenger with a claim of his own.', '[{"award":"Academy Awards","category":"Best Costume Design","result":"won","year":2019},{"award":"Academy Awards","category":"Best Production Design","result":"won","year":2019},{"award":"Academy Awards","category":"Best Original Score","result":"won","year":2019},{"award":"Academy Awards","category":"Best Picture","result":"nominated","year":2019}]'::jsonb, 'published', false),
('25cd9972-498c-5c45-ae58-5a058d0eb642', 'if-beale-street-could-talk', 'If Beale Street Could Talk', null, 2018, 'feature', array['US']::text[], array['English']::text[], array['Drama','Romance']::text[], 'In 1970s Harlem, a young woman fights to free her fiancé, falsely accused of a crime, before their child is born. Adapted from James Baldwin''s novel.', '[{"award":"Academy Awards","category":"Best Supporting Actress (Regina King)","result":"won","year":2019},{"award":"Independent Spirit Awards","category":"Best Feature","result":"won","year":2019}]'::jsonb, 'published', false),
('41a69978-a79c-5e15-a045-297827987749', 'sorry-to-bother-you', 'Sorry to Bother You', null, 2018, 'feature', array['US']::text[], array['English']::text[], array['Comedy','Science Fiction']::text[], 'An Oakland telemarketer discovers that using his ''white voice'' unlocks success, and a corporate conspiracy stranger than he could imagine.', '[{"award":"Independent Spirit Awards","category":"Best First Feature","result":"won","year":2019}]'::jsonb, 'published', false),
('c0ff2b2a-dfe8-54b2-a1be-842c92b899f1', 'hale-county-this-morning-this-evening', 'Hale County This Morning, This Evening', null, 2018, 'documentary', array['US']::text[], array['English']::text[], array['Documentary']::text[], 'An impressionistic portrait of two young men and their community in Alabama''s Black Belt, assembled from five years of footage.', '[{"award":"Sundance Film Festival","category":"Special Jury Award for Creative Vision","result":"won","year":2018},{"award":"Academy Awards","category":"Best Documentary Feature","result":"nominated","year":2019}]'::jsonb, 'published', false),
('86e3926a-ccb8-5851-aba8-84aac30013b9', 'us', 'Us', null, 2019, 'feature', array['US']::text[], array['English']::text[], array['Horror','Thriller']::text[], 'A family''s beach vacation is shattered when a group of doppelgängers appears in their driveway.', '[]'::jsonb, 'published', false),
('765b2f60-f668-5abb-a7f6-746788662d62', 'clemency', 'Clemency', null, 2019, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A prison warden who has overseen many executions confronts the toll of her job as she prepares to execute another man.', '[{"award":"Sundance Film Festival","category":"Grand Jury Prize, U.S. Dramatic","result":"won","year":2019}]'::jsonb, 'published', false),
('a032a40b-20ff-5a93-a997-b56c2fbf8cdb', 'time', 'Time', null, 2020, 'documentary', array['US']::text[], array['English']::text[], array['Documentary']::text[], 'Fox Rich fights for two decades for the release of her husband, sentenced to sixty years in prison, told through her own home videos.', '[{"award":"Sundance Film Festival","category":"Directing Award, U.S. Documentary","result":"won","year":2020},{"award":"Academy Awards","category":"Best Documentary Feature","result":"nominated","year":2021}]'::jsonb, 'published', false),
('9730c116-fca5-5860-ab1a-d7aa158a7b7e', 'judas-and-the-black-messiah', 'Judas and the Black Messiah', null, 2021, 'feature', array['US']::text[], array['English']::text[], array['Drama','Biography']::text[], 'An FBI informant infiltrates the Illinois Black Panther Party and its charismatic young chairman, Fred Hampton.', '[{"award":"Academy Awards","category":"Best Supporting Actor (Daniel Kaluuya)","result":"won","year":2021},{"award":"Academy Awards","category":"Best Original Song (\"Fight for You\")","result":"won","year":2021},{"award":"Academy Awards","category":"Best Picture","result":"nominated","year":2021}]'::jsonb, 'published', false),
('e0c6a209-99ee-56bc-a130-7e76fd46b2a1', 'a-thousand-and-one', 'A Thousand and One', null, 2023, 'feature', array['US']::text[], array['English']::text[], array['Drama']::text[], 'A mother takes her six-year-old son from the foster system, and they build a life together in a rapidly changing New York.', '[{"award":"Sundance Film Festival","category":"Grand Jury Prize, U.S. Dramatic","result":"won","year":2023}]'::jsonb, 'published', false),
('ad38af35-78fa-527d-a76e-9b08285a8f60', 'hair-love', 'Hair Love', null, 2019, 'animation', array['US']::text[], array['English']::text[], array['Animation','Family']::text[], 'A father tries to do his daughter''s hair for the first time, for a very important day.', '[{"award":"Academy Awards","category":"Best Animated Short Film","result":"won","year":2020}]'::jsonb, 'published', false),
('7ed3a2a9-3763-541f-a0da-128ecb66fcff', 'borom-sarret', 'Borom Sarret', null, 1963, 'short', array['SN']::text[], array['French','Wolof']::text[], array['Drama']::text[], 'A day in the life of a cart driver in Dakar. Often called the first film made in sub-Saharan Africa by a Black African director.', '[]'::jsonb, 'published', false),
('00e04111-7eba-59c4-ac8f-c11bcb528260', 'black-girl', 'Black Girl', 'La Noire de…', 1966, 'feature', array['SN','FR']::text[], array['French']::text[], array['Drama']::text[], 'A young Senegalese woman moves to the French Riviera to work for a white family and finds herself trapped, isolated and treated as a servant.', '[{"award":"Prix Jean Vigo","category":"Best Feature","result":"won","year":1966}]'::jsonb, 'published', true),
('88b82913-8c21-5a68-a47c-0d24fc10b5d7', 'badou-boy', 'Badou Boy', null, 1970, 'short', array['SN']::text[], array['Wolof','French']::text[], array['Comedy']::text[], 'A mischievous street kid is chased across Dakar by a hapless policeman.', '[]'::jsonb, 'published', false),
('d579fc3d-b72a-5f4a-a209-46dd163f1c9f', 'soleil-o', 'Soleil Ô', null, 1970, 'feature', array['MR','FR']::text[], array['French']::text[], array['Drama']::text[], 'An African accountant arrives in Paris full of hope, and runs into the racism of a country that calls him its child.', '[]'::jsonb, 'published', false),
('25e9b2bd-753f-51aa-ac33-8cbfcbd31258', 'sambizanga', 'Sambizanga', null, 1972, 'feature', array['AO','CG']::text[], array['Portuguese','Lingala','Kimbundu']::text[], array['Drama','History']::text[], 'In 1961, as the Angolan liberation war begins, a woman searches the prisons of Luanda for her husband, an activist arrested by the Portuguese.', '[{"award":"Carthage Film Festival","category":"Tanit d''Or","result":"won","year":1972}]'::jsonb, 'published', false),
('4ee84835-9509-502b-a682-e7675fbb3dd6', 'touki-bouki', 'Touki Bouki', null, 1973, 'feature', array['SN']::text[], array['Wolof','French']::text[], array['Drama']::text[], 'A cowherd and a student dream of escaping Dakar for Paris, and scheme to raise the money. A wild, dazzling road movie that never leaves home.', '[{"award":"Cannes Film Festival","category":"FIPRESCI Prize","result":"won","year":1973}]'::jsonb, 'published', true),
('4238b920-229d-5485-a9b6-11f2bbc7f7cd', 'xala', 'Xala', null, 1975, 'feature', array['SN']::text[], array['Wolof','French']::text[], array['Comedy','Drama']::text[], 'A wealthy businessman takes a third wife on the day of independence, only to be struck by a curse of impotence. A biting satire of the new elite.', '[]'::jsonb, 'published', false),
('f0921994-5f8b-51b7-a1d6-87fbd2615316', 'sugar-cane-alley', 'Sugar Cane Alley', 'Rue Cases-Nègres', 1983, 'feature', array['MQ','FR']::text[], array['French','Creole']::text[], array['Drama']::text[], 'In 1930s Martinique, a boy raised by his grandmother on a sugar plantation sees education as his way out.', '[{"award":"Venice Film Festival","category":"Silver Lion, Best First Work","result":"won","year":1983},{"award":"Venice Film Festival","category":"Volpi Cup, Best Actress (Darling Légitimus)","result":"won","year":1983},{"award":"César Awards","category":"Best First Feature","result":"won","year":1984}]'::jsonb, 'published', false),
('d344dd7c-0b71-5dcb-aa56-e7062217cb37', 'yeelen', 'Yeelen', null, 1987, 'feature', array['ML','BF','FR']::text[], array['Bambara']::text[], array['Drama','Fantasy']::text[], 'A young man with magical powers sets out across Mali to confront his father, a sorcerer determined to destroy him. Drawn from Bambara oral tradition.', '[{"award":"Cannes Film Festival","category":"Jury Prize","result":"won","year":1987}]'::jsonb, 'published', false),
('f8665bff-bef9-5960-a4a3-b22afc71a703', 'tilai', 'Tilaï', null, 1990, 'feature', array['BF','FR']::text[], array['Mooré']::text[], array['Drama']::text[], 'A man returns to his village to find that his father has married the woman he loved. Their affair breaks a law that cannot be broken.', '[{"award":"Cannes Film Festival","category":"Grand Prix","result":"won","year":1990},{"award":"FESPACO","category":"Étalon de Yennenga","result":"won","year":1991}]'::jsonb, 'published', false),
('ba00c703-d764-5f1f-a2d4-3f84bd6785a2', 'hyenas', 'Hyenas', 'Hyènes', 1992, 'feature', array['SN','FR']::text[], array['Wolof']::text[], array['Drama']::text[], 'A woman who left her village in disgrace returns rich beyond measure and offers a fortune for the death of the man who wronged her. Based on Dürrenmatt''s The Visit.', '[]'::jsonb, 'published', false),
('349417b6-68c1-506e-ad6a-0230f072edf6', 'quartier-mozart', 'Quartier Mozart', null, 1992, 'feature', array['CM']::text[], array['French']::text[], array['Comedy','Fantasy']::text[], 'A schoolgirl in a Yaoundé neighborhood is transformed by a sorceress into a young man, to learn how the other half lives.', '[]'::jsonb, 'published', false),
('079bf9a2-aaad-5559-a1d3-662ecdadc5e9', 'moolaade', 'Moolaadé', null, 2004, 'feature', array['SN','FR','BF']::text[], array['Bambara','French']::text[], array['Drama']::text[], 'A woman in a Burkinabé village offers protection to four girls fleeing ritual cutting, defying the elders. Sembène''s final film.', '[{"award":"Cannes Film Festival","category":"Un Certain Regard Prize","result":"won","year":2004}]'::jsonb, 'published', false),
('4eae5742-0098-5604-a680-37b5b369bcb2', 'bamako', 'Bamako', null, 2006, 'feature', array['ML','FR']::text[], array['French','Bambara']::text[], array['Drama']::text[], 'In a courtyard in Mali''s capital, a trial is staged: African society against the World Bank and the IMF, while daily life goes on around it.', '[]'::jsonb, 'published', false),
('22ccc007-927a-507d-aef7-90e97cdae1fe', 'the-figurine', 'The Figurine', 'Araromire', 2009, 'feature', array['NG']::text[], array['English','Yoruba']::text[], array['Thriller','Drama']::text[], 'Two friends find a mysterious statue in an abandoned shrine, and their fortunes change for seven years. A landmark of New Nollywood.', '[]'::jsonb, 'published', false),
('c1bfab03-b247-5c8a-a106-d87bc38a7461', 'a-screaming-man', 'A Screaming Man', 'Un homme qui crie', 2010, 'feature', array['TD','FR','BE']::text[], array['French','Arabic']::text[], array['Drama']::text[], 'A former swimming champion who works as a pool attendant at a hotel in N''Djamena loses his job to his own son as civil war closes in.', '[{"award":"Cannes Film Festival","category":"Jury Prize","result":"won","year":2010}]'::jsonb, 'published', false),
('2c2fba67-00c0-5b01-a796-a2a19dd4233c', 'timbuktu', 'Timbuktu', null, 2014, 'feature', array['MR','FR']::text[], array['French','Arabic','Tamasheq','Bambara']::text[], array['Drama']::text[], 'A cattle herder and his family live peacefully in the dunes outside Timbuktu, as jihadists occupy the city and ban music, laughter and football.', '[{"award":"César Awards","category":"Best Film","result":"won","year":2015},{"award":"César Awards","category":"Best Director","result":"won","year":2015},{"award":"Academy Awards","category":"Best Foreign Language Film","result":"nominated","year":2015}]'::jsonb, 'published', true),
('0cc07f8b-edef-55da-a21d-3dcb767b8054', 'felicite', 'Félicité', null, 2017, 'feature', array['SN','FR','BE','DE']::text[], array['Lingala','French']::text[], array['Drama']::text[], 'A proud bar singer in Kinshasa races across the city to raise money for her son''s operation after a motorcycle accident.', '[{"award":"Berlin International Film Festival","category":"Silver Bear Grand Jury Prize","result":"won","year":2017},{"award":"FESPACO","category":"Étalon de Yennenga","result":"won","year":2017}]'::jsonb, 'published', false),
('edc1879a-037d-5ea3-a092-ceced981dba2', 'i-am-not-a-witch', 'I Am Not a Witch', null, 2017, 'feature', array['GB','ZM','FR']::text[], array['Bemba','Nyanja','English']::text[], array['Comedy','Drama']::text[], 'After a minor incident in her village, a nine-year-old girl is accused of witchcraft and sent to a witch camp, where she is tied to a spool of white ribbon.', '[{"award":"BAFTA Awards","category":"Outstanding Debut by a British Writer, Director or Producer","result":"won","year":2018}]'::jsonb, 'published', false),
('4ef7460c-ac7e-577b-a3cd-3b460ede060b', 'rafiki', 'Rafiki', null, 2018, 'feature', array['KE','ZA','DE']::text[], array['Swahili','English']::text[], array['Romance','Drama']::text[], 'Two young women in Nairobi, whose fathers are political rivals, fall in love in a society that forbids it. The first Kenyan film selected for Cannes.', '[]'::jsonb, 'published', false),
('e0dcbc76-c68b-5269-ab1f-8969c646181c', 'atlantics', 'Atlantics', 'Atlantique', 2019, 'feature', array['SN','FR','BE']::text[], array['Wolof','French']::text[], array['Drama','Fantasy']::text[], 'In a Dakar suburb, unpaid construction workers set out across the ocean for Spain. The women they leave behind begin to be haunted by something strange.', '[{"award":"Cannes Film Festival","category":"Grand Prix","result":"won","year":2019}]'::jsonb, 'published', true),
('294d1bb2-6fe7-5eee-aaa9-f05c99535ff2', 'this-is-not-a-burial-it-s-a-resurrection', 'This Is Not a Burial, It''s a Resurrection', null, 2019, 'feature', array['LS','ZA']::text[], array['Sesotho']::text[], array['Drama']::text[], 'An eighty-year-old widow in a mountain village in Lesotho prepares for her own death, and then refuses to let her community be flooded for a dam.', '[]'::jsonb, 'published', false),
('2caa12ed-60e3-5a2e-a8ab-f3c6ce1a6966', 'on-becoming-a-guinea-fowl', 'On Becoming a Guinea Fowl', null, 2024, 'feature', array['ZM','GB','IE']::text[], array['Bemba','English']::text[], array['Drama','Comedy']::text[], 'Driving home from a party, a woman finds her uncle dead on the road. At his funeral, the family''s long-buried secrets surface.', '[{"award":"Cannes Film Festival","category":"Un Certain Regard, Best Director","result":"won","year":2024}]'::jsonb, 'published', false),
('d6ccb4b9-b1b8-570e-aa9d-8aaf636598c9', 'dahomey', 'Dahomey', null, 2024, 'documentary', array['FR','SN']::text[], array['French','Fon']::text[], array['Documentary']::text[], 'Twenty-six royal treasures looted by French troops in 1892 are returned from Paris to Benin. Part documentary, part fable, narrated by one of the objects.', '[{"award":"Berlin International Film Festival","category":"Golden Bear","result":"won","year":2024}]'::jsonb, 'published', false),
('e26fa163-e694-5554-a192-11fe273df5a4', 'pressure', 'Pressure', null, 1976, 'feature', array['GB']::text[], array['English']::text[], array['Drama']::text[], 'A British-born son of Trinidadian parents leaves school full of promise and runs into unemployment and racism, and his older brother''s Black Power activism.', '[]'::jsonb, 'published', false),
('d0662d51-7eb9-58c0-a7d5-64efa3cc2709', 'handsworth-songs', 'Handsworth Songs', null, 1986, 'documentary', array['GB']::text[], array['English']::text[], array['Documentary']::text[], 'Made by the Black Audio Film Collective in the wake of the 1985 riots in Birmingham and London, a poetic essay on race, migration and British history.', '[]'::jsonb, 'published', false),
('e478aac3-15bd-51b2-a8f0-ae4f0d89e8a5', 'looking-for-langston', 'Looking for Langston', null, 1989, 'short', array['GB']::text[], array['English']::text[], array['Drama']::text[], 'A black-and-white meditation on Langston Hughes and the Black gay artists of the Harlem Renaissance.', '[{"award":"Berlin International Film Festival","category":"Teddy Award","result":"won","year":1989}]'::jsonb, 'published', false),
('33c57569-e36a-525c-a75e-c13d94e5f87d', 'the-last-angel-of-history', 'The Last Angel of History', null, 1996, 'documentary', array['GB']::text[], array['English']::text[], array['Documentary']::text[], 'A time traveler searches for the code to the future in the work of Black musicians, artists and writers. A founding text of Afrofuturism.', '[]'::jsonb, 'published', false),
('8328e654-2ed7-557b-acb2-7586fd542a84', 'lumumba', 'Lumumba', null, 2000, 'feature', array['FR','BE','DE','HT']::text[], array['French']::text[], array['Biography','Drama']::text[], 'The rise and assassination of Patrice Lumumba, the first prime minister of the independent Congo.', '[]'::jsonb, 'published', false),
('ad903db6-99a2-50da-a113-a24c1fa006b6', 'hunger', 'Hunger', null, 2008, 'feature', array['GB','IE']::text[], array['English']::text[], array['Drama','History']::text[], 'Inside the Maze prison in 1981, IRA prisoner Bobby Sands leads a hunger strike to be recognized as a political prisoner.', '[{"award":"Cannes Film Festival","category":"Caméra d''Or","result":"won","year":2008}]'::jsonb, 'published', false),
('168891a4-e431-5532-a6eb-88f12d4f382e', 'belle', 'Belle', null, 2013, 'feature', array['GB']::text[], array['English']::text[], array['Drama','History']::text[], 'The mixed-race great-niece of the Lord Chief Justice is raised among the English aristocracy, as a landmark case about the slave trade comes before her uncle.', '[]'::jsonb, 'published', false),
('105be596-d836-5a86-a3f9-6104b7ee9921', 'i-am-not-your-negro', 'I Am Not Your Negro', null, 2016, 'documentary', array['US','FR','BE']::text[], array['English']::text[], array['Documentary']::text[], 'James Baldwin''s unfinished book about Medgar Evers, Malcolm X and Martin Luther King Jr., brought to the screen in his own words.', '[{"award":"BAFTA Awards","category":"Best Documentary","result":"won","year":2018},{"award":"Academy Awards","category":"Best Documentary Feature","result":"nominated","year":2017}]'::jsonb, 'published', false),
('ac1c4959-ef4a-577e-a459-27855526a31d', 'les-miserables', 'Les Misérables', null, 2019, 'feature', array['FR']::text[], array['French']::text[], array['Drama','Crime']::text[], 'A new police officer joins an anti-crime unit in Montfermeil, east of Paris, and a botched arrest caught on a drone camera threatens to set the estate alight.', '[{"award":"Cannes Film Festival","category":"Jury Prize","result":"won","year":2019},{"award":"César Awards","category":"Best Film","result":"won","year":2020}]'::jsonb, 'published', false),
('f087b63f-ced1-5c00-a3cf-67eace1316e1', 'saint-omer', 'Saint Omer', null, 2022, 'feature', array['FR']::text[], array['French']::text[], array['Drama']::text[], 'A novelist attends the trial of a young Senegalese woman accused of leaving her baby daughter on a beach to drown, and finds herself in the story.', '[{"award":"Venice Film Festival","category":"Grand Jury Prize","result":"won","year":2022},{"award":"Venice Film Festival","category":"Lion of the Future, Best Debut","result":"won","year":2022},{"award":"César Awards","category":"Best First Film","result":"won","year":2023}]'::jsonb, 'published', true),
('d4059513-221c-5c42-a09e-bd3558a54aa8', 'rye-lane', 'Rye Lane', null, 2023, 'feature', array['GB']::text[], array['English']::text[], array['Romance','Comedy']::text[], 'Two young Londoners, both reeling from bad breakups, meet in a gallery toilet and spend a day wandering South London together.', '[]'::jsonb, 'published', false),
('069c158b-e645-5322-a2a7-581e2e57bc8e', 'soul-in-the-eye', 'Soul in the Eye', 'Alma no Olho', 1973, 'short', array['BR']::text[], '{}'::text[], array['Experimental']::text[], 'Set to John Coltrane, a wordless film in which Bulbul performs the history of the African diaspora with his own body. A founding work of Black Brazilian cinema.', '[]'::jsonb, 'published', false)
