insert into public.collections (id, slug, title, description, kind, featured, sort_order) values
('a5be627c-0c44-5f36-ab24-928230cd8a86', 'la-rebellion', 'The L.A. Rebellion', 'In the 1970s and 80s, a group of Black students at UCLA set out to make films that had nothing to do with Hollywood. Their work, rooted in everyday Black life, reshaped American independent cinema.', 'movement', true, 0),
('908277fb-bb84-57d5-a112-c33655afbc4e', 'african-classics', 'Classics of African Cinema', 'From Sembène''s first features to the FESPACO prizewinners of the 1980s and 90s: the films that built a cinema of independence.', 'movement', true, 1),
('9a5a941c-9840-5ac9-a63f-39f21d59daf0', 'pioneers', 'Pioneers', 'The filmmakers who got there first, often with no money, no studio and no precedent.', 'theme', false, 2),
('7a668270-a9e7-59bc-a237-b208c6fc6c59', 'new-black-cinema', 'New Black Cinema', 'The late 1980s and early 90s, when a wave of young directors brought Black stories into multiplexes across America.', 'movement', false, 3),
('758391da-fece-5028-ab23-91361c9e1990', 'contemporary-africa', 'Contemporary African Cinema', 'A new generation of directors from across the continent and its diaspora, winning at Cannes, Berlin and Venice.', 'theme', true, 4),
('99f6eee7-9f92-5ed1-ac18-82877d71a1e1', 'black-british', 'Black British Cinema', 'From the workshop collectives of the 1980s to the present day.', 'country', false, 5),
('520f26a7-0374-5c42-aecf-d6c81f5b995f', 'black-queer-cinema', 'Black Queer Cinema', 'Films that put Black queer lives at the center.', 'theme', false, 6),
('5524e04c-5ee0-5f17-ac27-4bdc665e7183', 'documentaries', 'Essential Documentaries', 'Essay films, portraits and investigations.', 'genre', false, 7),
('a6fe879b-c933-5ce2-a05d-575c5959173d', 'cannes', 'Winners at Cannes', 'Films that took home prizes at the Cannes Film Festival.', 'theme', false, 8),
('56742524-bb24-5499-ae5e-4ea1d90793fa', 'oscar-winners', 'Academy Award Winners', 'Films that won at least one Oscar.', 'theme', false, 9),
('fa346452-c28f-5049-ab0e-e34451078820', 'sundance', 'Sundance Breakthroughs', 'Debuts and second features that broke out at Sundance.', 'theme', false, 10),
('b3a344e4-96f3-54f1-ae5f-0dfb39aacf09', 'shorts', 'Shorts & Animation', 'Short films, some of them the first steps of great careers.', 'genre', false, 11),
('79cb73d7-75c7-54ba-a228-fe65c2bdf76e', 'francophone', 'Francophone Cinema', 'Films from France, West and Central Africa and the Caribbean, in French and the languages spoken alongside it.', 'theme', false, 12)
