-- Starter catalog: 74 films, 236 people, 13 collections.
-- Generated by scripts/build-seed.mjs from data/starter.mjs. Safe to run again.
-- Run after schema.sql. Rows you've edited in the admin keep their posters, trailers and links.

on conflict (id) do update set slug = excluded.slug, name = excluded.name, bio = excluded.bio, country = excluded.country;

on conflict (id) do update set slug = excluded.slug, title = excluded.title, original_title = excluded.original_title, year = excluded.year, type = excluded.type, countries = excluded.countries, languages = excluded.languages, genres = excluded.genres, synopsis = excluded.synopsis, awards = excluded.awards, status = excluded.status, featured = excluded.featured;

on conflict (film_id, person_id, role) do nothing;

on conflict (id) do update set slug = excluded.slug, title = excluded.title, description = excluded.description, kind = excluded.kind, featured = excluded.featured, sort_order = excluded.sort_order;

on conflict (collection_id, film_id) do nothing;

